actionConfiguration.body:
SELECT *
FROM vw_lead
WHERE ({{ FiltroEtapa.selectedOptionValue || 0 }} = 0 OR etapa_id = {{ FiltroEtapa.selectedOptionValue || 0 }})
  AND ({{ FiltroOrigem.selectedOptionValue || 0 }} = 0 OR origem_id = {{ FiltroOrigem.selectedOptionValue || 0 }})
  AND (   nome    ILIKE {{ '%' + BuscaLead.text + '%' }}
       OR empresa ILIKE {{ '%' + BuscaLead.text + '%' }}
       OR email   ILIKE {{ '%' + BuscaLead.text + '%' }})
ORDER BY criado_em DESC;

SELECT *
FROM vw_lead
WHERE ({{ FiltroEtapa.selectedOptionValue || 0 }} = 0 OR etapa_id = {{ FiltroEtapa.selectedOptionValue || 0 }})
  AND ({{ FiltroOrigem.selectedOptionValue || 0 }} = 0 OR origem_id = {{ FiltroOrigem.selectedOptionValue || 0 }})
  AND (   nome    ILIKE {{ '%' + BuscaLead.text + '%' }}
       OR empresa ILIKE {{ '%' + BuscaLead.text + '%' }}
       OR email   ILIKE {{ '%' + BuscaLead.text + '%' }})
ORDER BY criado_em DESC;

function (lead) {
  const pontosPorOrigem = {
    2: 30,
    3: 20,
    4: 15,
    1: 10
  };
  let pontos = pontosPorOrigem[lead.origem_id] || 5;
  const cargo = (lead.cargo || '').toLowerCase();
  if ((/(diretor|ceo|s[oó]ci[oa]|presidente|propriet)/).test(cargo)) pontos += 25; else if ((/(gerente|coordenador|supervisor|head)/).test(cargo)) pontos += 15; else if (cargo.trim() !== '') pontos += 5;
  const valor = Number(lead.valor_estimado) || 0;
  if (valor >= 50000) pontos += 25; else if (valor >= 20000) pontos += 18; else if (valor >= 5000) pontos += 10; else if (valor > 0) pontos += 5;
  if ((lead.telefone || '').trim() !== '') pontos += 10;
  const interacoes = Number(lead.total_interacoes) || 0;
  if (interacoes >= 3) pontos += 10; else if (interacoes >= 1) pontos += 5;
  return Math.min(pontos, 100);
}

